import { doc, updateDoc, deleteDoc } from "firebase/firestore"; // Firebase функции
import { db } from "../../config/firebaseConfig"; // Конфигурация за Firebase

export async function markAsRead(messageId) {
    try {
        // Получаваме референция към документа за съобщението в колекцията 'messages'
        const messageRef = doc(db, "messages", messageId);

        // Маркираме съобщението като прочетено (ако искаш да го направиш)
        await updateDoc(messageRef, {
            isRead: true // Добавяме или променяме полето 'isRead' на true
        });

        // Изтриваме съобщението от Firestore
        await deleteDoc(messageRef);

        return { status: 200 }; // Връщаме успешен отговор
    } catch (error) {
        console.error("Error processing message:", error);
        throw new Error("Failed to process the message."); // Ако има грешка
    }
}
